css:
/* ==========================================================================
   Prime Exteriors - holding page
   Palette and type taken from the live site stylesheet so the page reads as
   the same brand while the rebuild is offline.
   ========================================================================== */
:root{
  --navy:#0B2E40; --char:#11415A; --deep:#072433;
  --aqua:#00C2DE; --aqua-bright:#36E0EC; --aqua-ink:#047E8F; --aqua-lite:#6FE6F2;
  --amber:#FFAC17; --amber-press:#E8930A;
  --ink:#16323F; --ondark:#DCEFF4; --ondark-mute:#A4C4CF;
  --fh:Archivo,"Barlow Semi Condensed","Helvetica Neue",Arial,sans-serif;
  --fb:Inter,"Source Sans 3","Helvetica Neue",Arial,sans-serif;
}
*,*::before,*::after{box-sizing:border-box}
html,body{height:100%}
body{
  margin:0; min-height:100%; color:var(--ondark);
  font:400 16px/1.6 var(--fb); background:var(--deep);
  display:grid; place-items:center; padding:28px 16px;
  -webkit-font-smoothing:antialiased;
}

/* ---- background ------------------------------------------------------- */
.pe-bg{position:fixed;inset:0;z-index:-2;overflow:hidden}
.pe-bg img{width:100%;height:100%;object-fit:cover;object-position:center 42%}
.pe-bg::after{
  content:"";position:absolute;inset:0;
  background:
    linear-gradient(168deg,rgba(7,36,51,.82) 0%,rgba(11,46,64,.7) 44%,rgba(7,36,51,.88) 100%),
    radial-gradient(120% 80% at 50% 0%,rgba(54,224,236,.16) 0%,transparent 62%);
}

/* ---- card ------------------------------------------------------------- */
.pe-card{
  width:100%;max-width:580px;text-align:center;position:relative;
  padding:52px 44px 48px;border-radius:22px;
  background:linear-gradient(168deg,rgba(14,52,70,.72) 0%,rgba(7,30,42,.82) 100%);
  border:1px solid rgba(111,230,242,.24);
  box-shadow:0 36px 90px rgba(3,16,24,.6),inset 0 1px 0 rgba(255,255,255,.08);
  -webkit-backdrop-filter:blur(16px) saturate(130%);backdrop-filter:blur(16px) saturate(130%);
  animation:peRise .7s cubic-bezier(.22,.61,.36,1) both;
}
@keyframes peRise{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}

.pe-logo{width:76px;height:76px;border-radius:18px;display:block;margin:0 auto 22px;
  background:#fff;padding:9px;box-shadow:0 10px 30px rgba(3,16,24,.4)}

.pe-eyebrow{display:inline-flex;align-items:center;gap:9px;margin:0 0 16px;
  font:700 11px/1 var(--fh);letter-spacing:.17em;text-transform:uppercase;color:var(--aqua-bright)}
.pe-dot{width:7px;height:7px;border-radius:50%;background:var(--aqua-bright);flex:0 0 7px;
  animation:pePulse 2.4s ease-out infinite}
@keyframes pePulse{
  0%{box-shadow:0 0 0 0 rgba(54,224,236,.6)}
  70%{box-shadow:0 0 0 10px rgba(54,224,236,0)}
  100%{box-shadow:0 0 0 0 rgba(54,224,236,0)}
}

h1{margin:0 0 16px;font:800 clamp(28px,5.2vw,42px)/1.08 var(--fh);
  letter-spacing:-.03em;color:#fff}
h1 em{font-style:normal;
  background:linear-gradient(96deg,var(--aqua-bright) 0%,#A5F0F8 60%,var(--aqua-lite) 100%);
  -webkit-background-clip:text;background-clip:text;color:transparent}
.pe-lede{margin:0 auto;max-width:48ch;font-size:17px;color:#C4DAE2}

/* ---- small screens ---------------------------------------------------- */
@media (max-width:560px){
  .pe-card{padding:36px 22px 30px;border-radius:18px}
  .pe-logo{width:64px;height:64px;margin-bottom:18px}
  .pe-lede{font-size:16px}
}

/* ---- reduced motion --------------------------------------------------- */
@media (prefers-reduced-motion:reduce){
  .pe-card,.pe-dot{animation:none}
}
